const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : {};
const rawBody = input.rawBody || JSON.stringify(body);

function getHeader(h, key) {
  const k = key.toLowerCase();
  for (const [n, v] of Object.entries(h)) {
    if (n.toLowerCase() === k) return Array.isArray(v) ? v[0] : v;
  }
}

const event = getHeader(headers, 'x-blacklabel-event');
const ts    = getHeader(headers, 'x-blacklabel-timestamp');
const sig   = getHeader(headers, 'x-blacklabel-signature');

if (event !== 'showroom_application.created') throw new Error(`Evento inválido: ${event || 'missing'}`);
if (!ts)  throw new Error('Falta x-blacklabel-timestamp');
if (!sig || !sig.startsWith('sha256=')) throw new Error('Falta x-blacklabel-signature');

const secret = process.env.N8N_WEBHOOK_DEALER_SIGNUP_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_DEALER_SIGNUP_SECRET no configurado');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const a = Buffer.from(sig);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Firma HMAC inválida');

const p = body;
const required = ['dealer_application_id', 'showroom_name', 'full_name', 'email', 'phone', 'city', 'admin_url'];
const missing = required.filter(f => !p[f]);
if (missing.length) throw new Error(`Payload incompleto: ${missing.join(', ')}`);

return [{ json: { ok: true, payload: p, received_at: new Date().toISOString() } }];

const d = $input.first().json;
const p = d.payload;
const MAIL_FROM    = process.env.MAIL_FROM    || 'Black Label Market <no-reply@blacklabelmarket.es>';
const ADMIN_EMAIL  = process.env.ADMIN_EMAIL  || 'aldeiaceo@gmail.com';
const MARKET_URL   = process.env.MARKET_URL   || 'https://blacklabelmarket.es';

const sources = [
  p.google_business_url ? `Google Business: ${p.google_business_url}` : null,
  p.instagram_url       ? `Instagram: ${p.instagram_url}`              : null,
  p.website_url || p.website ? `Web: ${p.website_url || p.website}`   : null,
  p.portal_url          ? `Portal: ${p.portal_url}`                    : null
].filter(Boolean).join('\n') || 'Sin URLs declaradas';

const confirmEmailHtml = `<p>Hola ${p.full_name},</p>
<p>Hemos recibido la solicitud de alta de <strong>${p.showroom_name}</strong> en Black Label Market.</p>
<p>Nuestro equipo revisará la información del showroom y las fuentes públicas disponibles. El proceso habitualmente tarda entre <strong>24 y 48 horas laborables</strong>.</p>
<p>Si necesitamos algún dato adicional, nos pondremos en contacto contigo. Mientras tanto puedes revisar el estado de tu solicitud en cualquier momento.</p>
<p>Gracias,<br>Black Label Market</p>`;

const internalEmailHtml = `<h2>Nueva solicitud de showroom</h2>
<p><strong>Showroom:</strong> ${p.showroom_name}</p>
<p><strong>Contacto:</strong> ${p.full_name} | ${p.email} | ${p.phone}</p>
<p><strong>Ubicación:</strong> ${p.city}${p.province ? ', ' + p.province : ''}</p>
<p><strong>Fuentes:</strong><br>${sources.replace(/\n/g, '<br>')}</p>
<p><a href="${p.admin_url}">Abrir solicitud en admin →</a></p>`;

const slackText = `*🔵 Nueva solicitud de showroom*\n\n*Showroom:* ${p.showroom_name}\n*Contacto:* ${p.full_name} (${p.email})\n*Ubicación:* ${p.city}${p.province ? ', ' + p.province : ''}\n*Teléfono:* ${p.phone}\n\n${sources}\n\n⏳ Iniciando investigación automática...\n\n<${p.admin_url}|Ver solicitud en el admin →>`;

return [{
  json: {
    payload: p,
    received_at: d.received_at,
    confirmEmail: {
      from: MAIL_FROM, to: [p.email],
      subject: 'Solicitud recibida — Black Label Market',
      html: confirmEmailHtml
    },
    internalEmail: {
      from: MAIL_FROM, to: [ADMIN_EMAIL],
      subject: `Nueva solicitud: ${p.showroom_name}`,
      html: internalEmailHtml
    },
    slackPayload: { text: slackText },
    MAIL_FROM, ADMIN_EMAIL, MARKET_URL
  }
}];

const d = $('Preparar contexto y emails').first().json;
const p = d.payload;
const KEY = process.env.FIRECRAWL_API_KEY;

async function scrape(url) {
  if (!url) return null;
  if (!KEY) return `[Sin FIRECRAWL_API_KEY — URL: ${url}]`;
  try {
    const res = await fetch('https://api.firecrawl.dev/v1/scrape', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ url, formats: ['markdown'], onlyMainContent: true, timeout: 15000 })
    });
    const json = await res.json();
    if (!json.success) return `[Error Firecrawl: ${json.error || 'sin detalle'}]`;
    const content = json.data?.markdown ?? '';
    return content.slice(0, 3000) || '[Contenido vacío]';
  } catch (e) {
    return `[Error de red: ${e.message}]`;
  }
}

const [googleContent, igContent, webContent, portalContent] = await Promise.all([
  scrape(p.google_business_url),
  scrape(p.instagram_url),
  scrape(p.website_url || p.website),
  scrape(p.portal_url)
]);

return [{
  json: {
    ...d,
    research: {
      google:    googleContent,
      instagram: igContent,
      website:   webContent,
      portal:    portalContent
    }
  }
}];

const d = $input.first().json;
const p = d.payload;
const r = d.research;

const prompt = `Eres analista interno de Black Label Market, un marketplace premium de vehículos de alta gama en España.
Evalúa esta solicitud de alta de showroom usando datos del formulario y señales públicas. El objetivo es preparar la revisión manual del equipo.

## DATOS DEL SOLICITANTE
- Showroom: ${p.showroom_name}
- Contacto: ${p.full_name} | ${p.email} | ${p.phone}
- Ubicación: ${p.city}${p.province ? ', ' + p.province : ''}
- Portales declarados: ${JSON.stringify(p.portals || p.portales || [])}

## CONTENIDO OBTENIDO

### Google Business
${r.google || 'No disponible'}

### Instagram
${r.instagram || 'No disponible'}

### Web oficial
${r.website || 'No disponible'}

### Portal de coches
${r.portal || 'No disponible'}

## INSTRUCCIONES
Genera un informe en español, sobrio y ejecutivo, con estas secciones exactas:

**1. RESUMEN EJECUTIVO** (2-3 frases)
**2. REPUTACIÓN** (nota Google, nº reseñas, calidad si disponible)
**3. ACTIVIDAD ONLINE** (antigüedad estimada, frecuencia, seguidores)
**4. ESPECIALIZACIÓN** (marcas, tipos de vehículos, posicionamiento)
**5. SEÑALES POSITIVAS** (puntos fuertes del negocio)
**6. SEÑALES DE ALERTA** (red flags; si no hay ninguno, indicar «Ninguna detectada»)
**7. RECOMENDACIÓN FINAL** → APROBAR / REVISAR MÁS / RECHAZAR con justificación de 1-2 frases

Reglas: no inventes datos no observados; indica si una fuente falla; usa lenguaje de análisis interno; prioriza evidencia verificable.`;

return [{
  json: {
    ...d,
    claudeRequest: {
      model: process.env.ANTHROPIC_MODEL || 'claude-haiku-4-5-20251001',
      max_tokens: 1500,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

const d = $('Preparar prompt Claude').first().json;
const claude = $input.first().json;
const p = d.payload;

let report = '';
if (Array.isArray(claude.content)) {
  report = claude.content.map(b => b.text || '').join('\n').trim();
} else if (claude.text) {
  report = claude.text;
} else if (claude.error) {
  report = `[Error Claude API: ${claude.error.message || JSON.stringify(claude.error)}]`;
} else {
  report = '[Informe no disponible — revisar credencial ANTHROPIC_API_KEY en n8n]';
}

const now = new Date().toISOString();
const adminNotes = `---\n[Informe automático ${now}]\nWorkflow: BLM — 1. Nueva Solicitud Showroom\nApplication ID: ${p.dealer_application_id}\n\n${report}`;

const ADMIN_EMAIL = process.env.ADMIN_EMAIL || d.ADMIN_EMAIL || 'aldeiaceo@gmail.com';
const MAIL_FROM   = process.env.MAIL_FROM   || d.MAIL_FROM   || 'Black Label Market <no-reply@blacklabelmarket.es>';

const summary = report.split('\n').filter(l => l.trim()).slice(0, 5).join('\n');

return [{
  json: {
    ...d,
    report,
    adminNotes,
    applicationId: p.dealer_application_id,
    supabaseUpdate: { admin_notes: adminNotes, status: 'in_review' },
    slackReportText: `*✅ Informe listo — acción requerida*\n\n*Showroom:* ${p.showroom_name}\n\n${summary}\n\n<${p.admin_url}|Revisar solicitud →>`,
    reportEmail: {
      from: MAIL_FROM, to: [ADMIN_EMAIL],
      subject: `Informe listo: ${p.showroom_name}`,
      html: `<h2>Informe automático listo</h2><p><strong>Showroom:</strong> ${p.showroom_name}</p><p><strong>Ubicación:</strong> ${p.city || ''}${p.province ? ', ' + p.province : ''}</p><p><a href="${p.admin_url}">Abrir en admin →</a></p><hr><pre style="white-space:pre-wrap;font-family:monospace">${report.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre>`
    }
  }
}];
